using System;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmStudentManagement:StyledForm { DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};TextBox name=T(),nrc=T(),phone=T(),email=T(),roll=T(),major=T(),academic=T(),address=T();NumericUpDown year=new NumericUpDown{Minimum=1,Maximum=5,Value=2};int id;static TextBox T(){return new TextBox{Width=245};}public FrmStudentManagement(){Text="Student Management";Size=new Size(1200,680);Controls.Add(g);var e=new TableLayoutPanel{Dock=DockStyle.Right,Width=300,Padding=new Padding(18),ColumnCount=1,AutoScroll=true};e.Controls.Add(new Label{Text="Existing Student",Font=new Font("Segoe UI",14,FontStyle.Bold),AutoSize=true});Add(e,"Student Name",name);Add(e,"NRC",nrc);Add(e,"Phone",phone);Add(e,"Email",email);Add(e,"University Roll Number",roll);Add(e,"Major",major);Add(e,"Current Year",year);Add(e,"Academic Year",academic);Add(e,"Address",address);var save=new Button{Text="Save Student",Width=150,Height=38};var clear=UiTheme.Secondary("New / Clear");var deactivate=UiTheme.Secondary("Deactivate / Restore");deactivate.Width=180;e.Controls.Add(save);e.Controls.Add(clear);e.Controls.Add(deactivate);Controls.Add(e);Controls.Add(UiTheme.Heading("Student Management","Create and update the existing student list for Years 2–5"));save.Click+=delegate{try{new StudentAdminQuery().Save(id,name.Text.Trim(),nrc.Text.Trim(),phone.Text.Trim(),email.Text.Trim(),roll.Text.Trim(),major.Text.Trim(),Convert.ToInt32(year.Value),academic.Text.Trim(),address.Text.Trim());LoadData();Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"Unable to save");}};clear.Click+=delegate{Clear();};deactivate.Click+=delegate{if(g.CurrentRow==null||g.CurrentRow.IsNewRow||g.CurrentRow.Cells["StudentId"].Value==DBNull.Value){MessageBox.Show("Select a student first.");return;}bool active=g.CurrentRow.Cells["IsActive"].Value!=DBNull.Value&&Convert.ToBoolean(g.CurrentRow.Cells["IsActive"].Value);string action=active?"deactivate":"restore";if(MessageBox.Show("Do you want to "+action+" this student?\r\n\r\nNo records will be permanently deleted.","Confirm Soft Delete",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){new StudentAdminQuery().SetActive(Convert.ToInt32(g.CurrentRow.Cells["StudentId"].Value),!active);LoadData();Clear();}};g.SelectionChanged+=delegate{LoadSelected();};Clear();LoadData();}void Add(TableLayoutPanel p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,8,3,2)});p.Controls.Add(c);}void LoadData(){g.DataSource=new StudentAdminQuery().All();if(g.Columns.Contains("StudentId"))g.Columns["StudentId"].Visible=false;}void LoadSelected(){if(g.CurrentRow==null||g.CurrentRow.IsNewRow||g.CurrentRow.Cells["StudentId"].Value==DBNull.Value)return;id=Convert.ToInt32(g.CurrentRow.Cells["StudentId"].Value);name.Text=Convert.ToString(g.CurrentRow.Cells["StudentName"].Value);nrc.Text=Convert.ToString(g.CurrentRow.Cells["NRC"].Value);phone.Text=Convert.ToString(g.CurrentRow.Cells["Phone"].Value);email.Text=Convert.ToString(g.CurrentRow.Cells["Email"].Value);roll.Text=Convert.ToString(g.CurrentRow.Cells["UniversityRollNo"].Value);major.Text=Convert.ToString(g.CurrentRow.Cells["Major"].Value);if(g.CurrentRow.Cells["Year"].Value!=DBNull.Value)year.Value=Convert.ToDecimal(g.CurrentRow.Cells["Year"].Value);academic.Text=Convert.ToString(g.CurrentRow.Cells["AcademicYear"].Value);address.Text=Convert.ToString(g.CurrentRow.Cells["Address"].Value);}void Clear(){id=0;name.Text=nrc.Text=phone.Text=email.Text=roll.Text=major.Text=address.Text="";year.Value=2;academic.Text=new SystemSettingsQuery().Get("AcademicYear");}}
}
